student-average.code:
#include <stdio.h>
struct student { int roll_no; char name[20]; float marks[10]; };
int main(void) {
    struct student s[100];
    int n, m;
    if (scanf("%d%d", &n, &m) != 2 || n < 1 || n > 100 || m < 1 || m > 10)
        return 1;
    for (int i = 0; i < n; ++i) {
        if (scanf("%d%19s", &s[i].roll_no, s[i].name) != 2) return 1;
        double sum = 0;
        for (int j = 0; j < m; ++j) {
            if (scanf("%f", &s[i].marks[j]) != 1 ||
                !(s[i].marks[j] >= 0 && s[i].marks[j] <= 100)) return 1;
            sum += s[i].marks[j];
        }
        printf("%d %s average=%.2f\n", s[i].roll_no, s[i].name, sum / m);
    }
    return 0;
}

