swap.code:
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void value_swap(int x, int y) {
    int t = x;
    x = y;
    y = t;
    printf("Local: %d %d\n", x, y);
}
static void address_swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}
int main(void) {
    int a = 2, b = 3;
    value_swap(a, b);
    printf("Caller: %d %d\n", a, b);
    address_swap(&a, &b);
    printf("Caller: %d %d\n", a, b);
}

