#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void sort(int a[], int n) {
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - i - 1; j++)
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
}
int main(void) {
    int a[] = {4, 2, 9, 1, 7};
    int n = 5;
    sort(a, n);
    for (int i = 0; i < n; i++)
        printf("%d%s", a[i], i + 1 == n ? "\n" : " ");
}

