int main(void) {
    int *p = malloc(2 * sizeof *p);
    if (!p)
        return EXIT_FAILURE;
    p[0] = 10;
    p[1] = 20;
    int *zero = calloc(2, sizeof *zero);
    if (!zero) {
        free(p);
        return EXIT_FAILURE;
    }
    printf("calloc: %d %d\n", zero[0], zero[1]);
    free(zero);
    int *tmp = realloc(p, 3 * sizeof *p);
    if (!tmp) {
        free(p);
        return EXIT_FAILURE;
    }
    p = tmp;
    p[2] = 30;
    printf("%d %d %d\n", p[0], p[1], p[2]);
    free(p);
}

